	}
	if !config.Present || config.Version != StudyConfigVersion {
		t.Fatalf("config = %#v", config)
	}
	if len(order) != 2 || order[0].Ref() != "02-runtime" || order[1].Ref() != "01-structure" {
		t.Fatalf("order = %#v", order)
