		t.Fatalf("status = %d stdout = %q stderr = %q", status, stdout, stderr)
	}
	assertContains(t, stderr, "requires <study-init.yml>")
}

func TestStudyInitDryRunOutputAndNoMutation(t *testing.T) {
	dir := initializedWorkspace(t)
