	stdout, stderr, status = runForTest([]string{"--workspace", dir, "study", "demo", "prompt", "analysis", "01", "repo", "--output", "previews/repo.prompt.md"})
	if status != ExitOK {
		t.Fatalf("output status = %d, stdout = %q stderr = %q", status, stdout, stderr)
